async function testIdempotentPatch(client, id, payload, repeats=3){
  for(let i=0;i<repeats;i++){ await client.patch(`/accounts/${id}`, payload); }
}

// Pseudocode: streaming dedupe
let lastSeq = 0;
stream.on('data', ev => { if (ev.seq>lastSeq){ lastSeq=ev.seq; process(ev); } });
